// Unpack the items array into separate n8n items for looping
const items = $json.items || [];
if (!items.length) {
  return [];
}

return items.map(item => ({
  json: item
}));

// Clean and format AI response
const aiResponse = $json.choices?.[0]?.message?.content || '{}';
let parsed = {};
try {
  parsed = JSON.parse(aiResponse);
} catch (e) {
  const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try { parsed = JSON.parse(jsonMatch[0]); } catch {}
  }
}

const originalItem = $('Loop Over Each Flyer').item.json;

// Sanitize disclosure factor payments (e.g. $16.67 per $1,000 financed or $15.15 per $1,000 borrowed)
let cleanMonthly = parsed.monthly_payment != null ? Number(parsed.monthly_payment) : null;
let cleanApr = parsed.apr != null ? Number(parsed.apr) : null;
let cleanType = parsed.special_type || 'lease';

const discText = `${parsed.title || ''} ${parsed.disclaimer || ''} ${originalItem.rawText || ''}`.toLowerCase();
if (cleanMonthly != null && cleanMonthly < 80) {
  if (
    cleanApr != null ||
    discText.includes('per $1,000') ||
    discText.includes('per $1000') ||
    discText.includes('per thousand') ||
    discText.includes('per 1,000') ||
    discText.includes('per 1000')
  ) {
    cleanMonthly = null;
    if (cleanApr != null) {
      cleanType = 'apr';
    }
  }
}

const hasNumericTerms = (
  (cleanMonthly != null && cleanMonthly > 0) ||
  (cleanApr != null && cleanApr >= 0) ||
  (parsed.down_payment != null && Number(parsed.down_payment) >= 0) ||
  (parsed.term_months != null && Number(parsed.term_months) > 0) ||
  (parsed.msrp != null && Number(parsed.msrp) > 0) ||
  (parsed.offer_details && String(parsed.offer_details).trim().length > 0)
);

const isSpecial = parsed.is_special !== false && hasNumericTerms;

return {
  json: {
    staging_id: originalItem.id,
    image_hash: originalItem.imageHash || null,
    auto_approve: isSpecial,
    status: isSpecial ? 'approved' : 'discarded',
    discard: !isSpecial,
    discard_reason: !isSpecial ? 'No actionable financial special terms (empty card avoided)' : null,
    raw_text: originalItem.rawText || '',
    extracted_data: {
      is_special: isSpecial,
      year: parsed.year || new Date().getFullYear(),
      make: parsed.make || 'Unknown',
      model: parsed.model || 'Special Offer',
      trim: parsed.trim || null,
      special_type: cleanType,
      monthly_payment: cleanMonthly,
      term_months: parsed.term_months != null ? Number(parsed.term_months) : null,
      down_payment: parsed.down_payment != null ? Number(parsed.down_payment) : null,
      apr: cleanApr,
      msrp: parsed.msrp != null ? Number(parsed.msrp) : null,
      offer_details: parsed.offer_details || null,
      title: parsed.title || originalItem.title || '',
      disclaimer: parsed.disclaimer || originalItem.disclaimer || '',
      expiration_date: parsed.expiration_date || null
    }
  }
};
